void processBlock(juce::AudioBuffer<float>& buffer, juce::MidiBuffer&) override {
    juce::ScopedNoDenormals noDenormals;

    // Feedback path with denormal prevention
    for (int i = 0; i < buffer.getNumSamples(); ++i) {
        float input = buffer.getReadPointer(0)[i];
        float output = input + feedbackBuffer[feedbackPos];
        feedbackBuffer[feedbackPos] = output * feedbackGain + 1e-18f;  // Denormal offset
        feedbackPos = (feedbackPos + 1) % feedbackBuffer.size();
        buffer.getWritePointer(0)[i] = output;
    }
}
